            "content": "from typing import List


def longest_subarray_with_limited_diff(arr: List[int], k: int) -> int:
    if not arr:
        return 0

    left = 0
    max_length = 0

    for right in range(len(arr)):
        while max(arr[left:right + 1]) - min(arr[left:right + 1]) > k:
            left += 1
        max_length = max(max_length, right - left + 1)

    return max_length

# Test cases

def test_longest_subarray_with_limited_diff():
    assert longest_subarray_with_limited_diff([1, 3, 2, 4, 5], 2) == 3
    assert longest_subarray_with_limited_diff([], 2) == 0
    assert longest_subarray_with_limited_diff([1, 1, 1, 1], 0) == 4
    assert longest_subarray_with_limited_diff([1, 5, 6, 7], 1) == 1

# Run tests
